<?php
function cssrRenderStockPage(array $data,array $ui,array $options): void
{
    $e='cssrUiEscape';$preview=!empty($options['preview']);$route=$options['route']??'cssr_available_stock.php';
    $url=fn($changes=[])=>$route.'?'.http_build_query(array_merge(['q'=>$data['q'],'status'=>$data['status'],'month'=>$data['month'],'page'=>$data['page']],$changes));
    $badge=fn($status)=>['Available'=>'success','Low Stock'=>'warning','Out of Stock'=>'danger','Reserved'=>'info','Verify batch'=>'warning','Expired'=>'danger','On Hold'=>'danger','Empty'=>'danger'][$status]??'';
    $ui['styles'][]='../assets/css/cssr-stock.css?v='.filemtime(__DIR__.'/../assets/css/cssr-stock.css');
    $ui['scripts'][]='../assets/js/cssr-stock.js?v='.filemtime(__DIR__.'/../assets/js/cssr-stock.js');cssrUiStart($ui);
?>
<div class="cu-page-heading"><div><p class="cu-eyebrow">Department supply operations</p><h1>CSSR Stock</h1><p class="cu-lead cu-muted">Supplies inside CSSR, ready for department replenishment.</p></div><span class="cs-location"><?=cssrUiIcon('box')?>CSSR only</span></div>
<div class="cu-stack">
<?php if($preview): ?><p class="cu-alert">Design preview · Sample CSSR balances and issuance only. No hospital records are changed.</p><?php endif; ?>
<section class="cu-stats" aria-label="CSSR stock summary">
<?php foreach([
    ['total','Total CSSR Stock','box','Usable units physically inside CSSR'],
    ['low','Low Stock','warning','Items below their reorder level'],
    ['out','Out of Stock','box','CSSR items with no usable stock'],
    ['fast','Fast-Moving Items','report','Top 20% by monthly issued quantity; ties included'],
] as [$key,$label,$icon,$help]): ?><article class="cu-card cu-stat cs-stat-<?=$key?>"><div class="cu-stat-top"><span><?=$label?></span><span class="cu-icon-tile"><?=cssrUiIcon($icon)?></span></div><strong class="cu-stat-value"><?=number_format($data['stats'][$key])?></strong><small><?=$help?></small></article><?php endforeach; ?></section>
<div class="cs-availability"><div><span class="cu-icon-tile"><?=cssrUiIcon('issue')?></span><span><strong><?=number_format($data['stats']['ready'])?> units available for new requests</strong><small><?=number_format($data['stats']['reserved'])?> units reserved for approved requests<?php if($data['stats']['legacy']>0): ?> · <?=number_format($data['stats']['legacy'])?> units awaiting batch verification<?php endif; ?></small></span></div><p>Storage Room 1 quantities are excluded.</p></div>
<section class="cu-card"><form class="cs-filters" action="<?=$e($route)?>" role="search" aria-label="Filter CSSR stock"><div class="cu-field"><label for="cs-search">Search CSSR stock</label><input class="cu-input" id="cs-search" name="q" type="search" placeholder="Item name or item code" value="<?=$e($data['q'])?>"></div><div class="cu-field"><label for="cs-status">Status</label><select class="cu-input" name="status" id="cs-status"><option value="">All statuses</option><?php foreach($data['statuses'] as $status): ?><option <?=$status===$data['status']?'selected':''?>><?=$status?></option><?php endforeach; ?></select></div><div class="cu-field"><label for="cs-month">Issuance month</label><input class="cu-input" id="cs-month" name="month" type="month" value="<?=$e($data['month'])?>" max="<?=date('Y-m')?>"></div><div class="cu-actions"><button class="cu-btn" type="submit">Apply filters</button><a class="cu-btn cu-btn-ghost" href="<?=$e($route)?>">Reset</a></div></form>
<div class="cu-card-head"><div><h2>Department issuance stock</h2><p>Stock balances are current. Monthly issuance: <?=$e($data['month_label'])?>.</p></div><span class="cu-badge"><?=$data['total']?> items</span></div>
<div class="cu-table-wrap" tabindex="0" role="region" aria-label="CSSR stock table; scroll horizontally for additional columns"><table class="cu-table cs-table"><thead><tr><th scope="col">Item Code</th><th scope="col">Item Name</th><th scope="col" class="cu-center cs-stock-heading">Current CSSR Stock</th><th scope="col" class="cu-center">Reorder Level</th><th scope="col" class="cu-center">Monthly Issued Quantity</th><th scope="col">Status</th><th scope="col">Action</th></tr></thead><tbody>
<?php foreach($data['rows'] as $row): ?><tr data-cs-row="<?=(int)$row['id']?>"><td><?=$e($row['item_code'])?></td><td><strong><?=$e($row['item_name'])?></strong><?php if($row['fast_moving']): ?><span class="cu-badge cu-badge-info cs-fast">Fast-moving</span><?php endif; ?></td><td class="cs-stock cu-center <?=$row['current_cssr_stock']===0?'cs-stock-zero':''?>"><strong><?=number_format($row['current_cssr_stock'])?></strong><span><?=$e($row['unit'])?></span><?php if($row['ready_quantity']!==$row['current_cssr_stock']): ?><small><?=number_format($row['ready_quantity'])?> for new requests</small><?php endif; ?></td><td class="cu-center"><?=number_format((int)$row['minimum_stock'])?></td><td class="cu-center"><strong><?=number_format($row['monthly_issued'])?></strong><small><?=$e($row['unit'])?> issued</small></td><td><span class="cu-badge cu-badge-<?=$badge($row['stock_status'])?>"><?=$row['stock_status']?></span><?php if($row['held']>0): ?><small><?=number_format($row['held'])?> held / expired</small><?php endif; ?></td><td><a class="cu-btn cu-btn-secondary cu-btn-sm" href="<?=$e($url(['view'=>$row['id']]))?>" aria-label="View CSSR stock for <?=$e($row['item_name'])?>">View <?=cssrUiIcon('chevron')?></a></td></tr><?php endforeach; ?>
<?php if(!$data['rows']): ?><tr><td colspan="7"><div class="cu-empty"><span class="cu-icon-tile"><?=cssrUiIcon('box')?></span><h3>No CSSR items found</h3><p>Adjust the filters or transfer supplies into CSSR.</p><a class="cu-btn cu-btn-secondary" href="<?=$e($route)?>">Clear filters</a></div></td></tr><?php endif; ?></tbody></table></div>
<footer class="cu-table-foot"><span><?=$data['total']?($data['page']-1)*10+1:0?>–<?=min($data['page']*10,$data['total'])?> of <?=$data['total']?> items</span><nav class="cu-actions" aria-label="CSSR stock pages"><?php if($data['page']>1): ?><a class="cu-btn cu-btn-secondary cu-btn-sm" href="<?=$e($url(['page'=>$data['page']-1]))?>">Previous</a><?php endif; ?><span>Page <?=$data['page']?> of <?=$data['pages']?></span><?php if($data['page']<$data['pages']): ?><a class="cu-btn cu-btn-secondary cu-btn-sm" href="<?=$e($url(['page'=>$data['page']+1]))?>">Next</a><?php endif; ?></nav></footer></section>
<p class="cs-note cu-muted"><?=cssrUiIcon('history')?>CSSR receipts and transfers in − issues − returns sent out + accepted department returns. Posted opening balances and corrections are included.</p>
</div>
<?php if($detail=$data['detail']): ?>
<dialog class="cu-dialog cs-detail" id="cs-detail" aria-labelledby="cs-detail-title" data-item-id="<?=(int)$detail['id']?>"><header class="cu-dialog-head"><div><p class="cu-eyebrow">CSSR stock details</p><h2 id="cs-detail-title"><?=$e($detail['item_name'])?></h2><small class="cu-muted"><?=$e($detail['item_code'])?></small></div><button class="cu-icon-button" type="button" data-cu-dismiss aria-label="Close stock details" autofocus><?=cssrUiIcon('close')?></button></header><div class="cs-detail-body">
<div class="cs-detail-balance"><div><span>Current CSSR Stock</span><strong><?=number_format($detail['current_cssr_stock'])?> <small><?=$e($detail['unit'])?></small></strong></div><span class="cu-badge cu-badge-<?=$badge($detail['stock_status'])?>"><?=$detail['stock_status']?></span></div>
<dl class="cs-breakdown"><?php foreach(['For new requests'=>$detail['ready_quantity'],'Reserved'=>$detail['reserved'],'Held / expired'=>$detail['held'],'Reorder level'=>$detail['minimum_stock']] as $label=>$quantity): ?><div><dt><?=$label?></dt><dd><?=number_format((int)$quantity)?></dd></div><?php endforeach; ?></dl>
<?php if($detail['legacy_stock']>0): ?><p class="cu-alert cs-legacy"><?=number_format($detail['legacy_stock'])?> units are recorded in earlier CSSR stock records. Verify their batch records before releasing them through requisitions.</p><?php endif; ?>
<h3>CSSR batches</h3><p class="cs-description cu-muted">Only CSSR records appear here. Reserved stock stays in CSSR until released; held and expired quantities are excluded from usable stock.</p>
<div class="cu-table-wrap" tabindex="0" role="region" aria-label="CSSR batch balances"><table class="cu-table cs-batches"><thead><tr><th>Batch / Lot</th><th>Expiration Date</th><th class="cu-center">Physical Quantity</th><th class="cu-center">Usable Stock</th><th class="cu-center">Reserved</th><th>Status</th></tr></thead><tbody><?php foreach($detail['lots'] as $lot): ?><tr><td><?=$e($lot['lot_number']?:'Unidentified')?></td><td><?=$e($lot['expiry_date']?:'No expiry')?></td><td class="cu-center"><?=number_format($lot['physical'])?></td><td class="cu-center"><?=number_format($lot['usable'])?></td><td class="cu-center"><?=number_format($lot['reserved'])?></td><td><span class="cu-badge cu-badge-<?=$badge($lot['status'])?>"><?=$lot['status']?></span></td></tr><?php endforeach; ?></tbody></table></div>
<div class="cs-issues-heading"><h3>Issued in <?=$e($data['month_label'])?></h3><strong><?=number_format($detail['monthly_issued'])?> <?=$e($detail['unit'])?></strong></div><p class="cs-description cu-muted">Gross quantity issued from CSSR. Returns are recorded separately. Showing the latest 25 issuance entries.</p>
<div class="cu-table-wrap" tabindex="0" role="region" aria-label="Monthly CSSR issuance"><table class="cu-table cs-issues"><thead><tr><th>Date</th><th>Reference</th><th>Department</th><th>Batch / Lot</th><th class="cu-center">Quantity</th></tr></thead><tbody><?php foreach($data['issues'] as $issue): ?><tr><td><?=$e($issue['issued_date'])?></td><td><?=$e($issue['reference_no'])?></td><td><?=$e($issue['department'])?></td><td><?=$e($issue['lot_number'])?></td><td class="cu-center"><?=number_format((int)$issue['quantity_issued'])?></td></tr><?php endforeach; ?><?php if(!$data['issues']): ?><tr><td colspan="5"><div class="cu-empty">No CSSR issuance recorded in this month.</div></td></tr><?php endif; ?></tbody></table></div>
</div><footer class="cu-dialog-foot"><button class="cu-btn cu-btn-secondary" type="button" data-cu-dismiss>Close</button><?php if(!empty($options['requests'])): ?><a class="cu-btn" href="<?=$e($options['requests'])?>">Open Requisitions <?=cssrUiIcon('chevron')?></a><?php endif; ?></footer></dialog>
<?php elseif(!empty($_GET['view'])): ?><p class="cu-alert">This item has no accessible CSSR stock record.</p><?php endif; ?>
<?php cssrUiEnd();
